/tr><tr><td>Sel rekening keuangan terisi</td><td><?= $financial ?></td></tr><tr><td>Dokumen pendukung</td><td><?= count($docs) ?></td></tr></table><h2>Dokumen pendukung</h2><ol><?php foreach ($docs as $d): ?><li><?= h($d['type_name']?:'Dokumen') ?>: <?= h($d['original_name']) ?> — <?= $d['verification_status']==='approved'?'Disetujui':'Belum disetujui' ?></li><?php endforeach; ?><?php if (!$docs): ?><li>Belum ada dokumen.</li><?php endif; ?></ol><h2>Catatan pemeriksaan kelengkapan</h2><p><?= $review_note && isset($review_note['note'])?nl2br(h($review_note['note'])):'Belum ada catatan pemeriksaan OPD.' ?></p><?php if ($review): ?><p>Dicatat oleh <?= h($review['full_name']?:'Petugas') ?> pada <?= h($review['created_at']) ?>.</p><?php endif; ?><p class="notice">Dokumen ini disusun otomatis dari data yang tersimpan untuk pemeriksaan dan tanda tangan petugas. Nilai, predikat kesehatan, nomor naskah resmi, dan sertifikat belum dihasilkan karena rumus dan penetapannya masih dalam validasi.</p><div class="sign"><div>Petugas pemeriksa<br><br><br><br>(........................)</div><div>Perwakilan koperasi<br><br><br><br>(........................)</div></div><p><small>Dicetak <?= date('d-m-Y H:i') ?> · SIKOP Rembang</small></p><button onclick="window.print()">Cetak draf</button></body></html>
